// Spam scoring. SimpleHash (the industry's spam-score API) shut down in
// March 2025, so this is our own transparent heuristic stack instead of an
// opaque third-party score. Every signal is explainable to the user, which
// matters: false positives hide real assets.
import { checkTextForDomains } from './blocklist.js'

// Signals, each with a weight. Score >= SPAM_THRESHOLD → hidden by default
// (always reversible by the user). Weights were calibrated against a real
// wallet's holdings — weak signals like "no artwork" must never flag alone.
export const SPAM_THRESHOLD = 4

// Brands whose names/URLs get copied wholesale by impersonation drops. If
// metadata claims one of these but the contract is anonymous, it's a fake.
const IMPERSONATED = /veefriends|boredape|yuga|azuki|pudgy|doodles|moonbird|clonex|opensea|uniswap|shiba|pancakeswap|lido|st\.?eth|laye?r ?zero|arbitrum|optimism|blur|metamask|ledger|trezor|coinbase|binance/i

// Words that turn a brand mention into a lure. A real project ships "Lido
// Withdrawal NFT"; a drainer ships "LIDO ST.ETH NFT COUPON — YOU HAVE WON".
const BAIT = /coupon|voucher|ticket|pass\b|prize|winner|you have won|\bwon\b|claim|reward|gift|airdrop|giveaway|eligible|redeem|bonus/i

// Any domain-shaped token. Deliberately generic (country TLDs like .pl are
// used constantly by these drops); digits before the dot don't match, so
// "Uniswap - 0.3% - PRO/WETH" and "v1.2" stay clean.
const TLD = /\b[a-z0-9][a-z0-9-]{1,}\.[a-z]{2,6}\b/i

// Collection names that are random strings (base64-ish IDs, no vowel/space
// structure) are throwaway contracts, never real projects.
const GIBBERISH = (s) => {
  if (!s || /\s/.test(s) || s.length < 12) return false
  const letters = s.replace(/[^a-zA-Z]/g, '')
  if (letters.length < 10) return false
  const caseFlips = [...letters].filter((c, i, a) => i && (c === c.toUpperCase()) !== (a[i - 1] === a[i - 1].toUpperCase())).length
  return caseFlips / letters.length > 0.25
}

// Domain-name NFTs (ENS, Unstoppable) legitimately have a domain AS the name,
// so the URL rule must not fire on them.
const DOMAIN_COLLECTION = /unstoppable domains|ethereum name service|\bens\b|name service|\.bit\b|space id/i

// PFP collections that only exist on Ethereum mainnet. The same name on
// another chain is an impersonation, no lure word required.
const ETHEREUM_ONLY = /pudgy|azuki|boredape|bored ape|mutant ape|veefriends|doodles|moonbird|clonex|cryptopunk|meebit/i

// Most lures live in the collection name as often as the token name, so
// text rules scan both.
const txt = (n) => `${n.name || ''} ${n.collectionName || ''}`

const RULES = [
  { w: 6, code: 'indexer-flag', test: (n) => n.flaggedScam, why: 'flagged as a scam by the block explorer' },
  // Drainer airdrops mint from throwaway contracts that never set name or
  // symbol. Legitimate collections essentially always do. Verified against a
  // real wallet: caught 6 impersonation drops, missed no genuine holding.
  { w: 4, code: 'anonymous-contract', test: (n) => !n.collectionName && !n.collectionSymbol, why: 'from an unnamed contract (no collection name or symbol)' },
  // The nastiest variant copies a real project's name, description and even
  // its website, and hides the phishing lure inside the artwork itself.
  { w: 5, code: 'impersonation', test: (n) => !n.collectionName && IMPERSONATED.test(`${n.name} ${n.description || ''} ${n.externalUrl || ''}`), why: 'anonymous contract impersonating a known project' },
  { w: 3, code: 'url-in-description', test: (n) => !n.collectionName && /(https?:\/\/|www\.)/i.test(n.description || ''), why: 'unnamed contract with links in its description' },
  { w: 4, code: 'url-in-name', test: (n) => !DOMAIN_COLLECTION.test(n.collectionName || '') && (/(https?:\/\/|www\.)/i.test(txt(n)) || TLD.test(txt(n))), why: 'contains a web address' },
  { w: 4, code: 'wrong-chain-brand', test: (n) => ETHEREUM_ONLY.test(txt(n)) && Number(n.chainId) !== 1, why: 'claims an Ethereum-only collection but lives on another chain' },
  { w: 4, code: 'gibberish-collection', test: (n) => GIBBERISH(n.collectionName), why: 'random-string collection name (throwaway contract)' },
  // A brand name plus a lure word, from a contract that isn't that brand's.
  // Catches named-contract impersonations the anonymous-contract rule misses.
  { w: 4, code: 'brand-bait', test: (n) => IMPERSONATED.test(`${n.name} ${n.collectionName || ''}`) && BAIT.test(`${n.name} ${n.collectionName || ''}`), why: 'impersonates a known project with a giveaway lure' },
  { w: 4, code: 'money-bait', test: (n) => /(\$\s?\d|\d+\s?(eth|usd|usdt|sol|matic)\b|\bfree\b|claim|reward|voucher|giveaway|airdrop|earning|drop\b)/i.test(txt(n)), why: 'promises free money' },
  { w: 4, code: 'pass-bait', test: (n) => /\bnft\s?(pass|drop|voucher|ticket|access|coupon|reward|gift)\b|nftpass/i.test(txt(n)), why: 'fake "NFT pass/coupon" bait' },
  { w: 4, code: 'amount-bait', test: (n) => /[$€]\s?\d{2,}|\b\d{2,}\s?(usdt|usdc|eth|bnb|sol|matic)\b/i.test(txt(n)) && BAIT.test(txt(n)), why: 'names a cash amount next to a lure word' },
  { w: 3, code: 'instruction-bait', test: (n) => /(scan (the |this )?qr|visit |go to |claim at|get a reward|open (the )?link)/i.test(txt(n)), why: 'instructs you to visit or scan something' },
  { w: 3, code: 'range-bait', test: (n) => /\b\d{3,}\s*(to|-|–|→)\s*\d{3,}\b/i.test(txt(n)), why: 'promises a payout range' },
  { w: 2, code: 'urgency', test: (n) => /(hurry|expire|last chance|act now|limited|winner|congratulation|\bwin\b)/i.test(txt(n)), why: 'uses urgency language' },
  { w: 2, code: 'emoji-spam', test: (n) => ((n.name.match(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu) || []).length >= 3), why: 'heavy emoji use' },
  { w: 1, code: 'no-image', test: (n) => !n.images?.length, why: 'has no artwork' },
  { w: 1, code: 'shouty', test: (n) => n.name.length > 12 && n.name === n.name.toUpperCase(), why: 'ALL CAPS name' },
]

export async function scoreNft(n) {
  const hits = RULES.filter((r) => { try { return r.test(n) } catch { return false } })
  let score = hits.reduce((s, r) => s + r.w, 0)
  const reasons = hits.map((r) => r.why)

  // phishing domain inside the name is decisive
  const dom = await checkTextForDomains(n.name)
  if (dom.verdict === 'blocked' || dom.verdict === 'fuzzy') {
    score += 6
    reasons.unshift(`contains known phishing domain (${dom.host})`)
  }
  return { score, spam: score >= SPAM_THRESHOLD, reasons }
}

export async function scoreAll(nfts) {
  return Promise.all(nfts.map(async (n) => {
    const { score, spam, reasons } = await scoreNft(n)
    return { ...n, spamScore: score, spam: spam || n.spam, spamReasons: reasons }
  }))
}
