// Outbound links are checked against the phishing blocklists before they open.
// NFT metadata is attacker-controlled, so "Raw image" and any metadata-derived
// URL is a potential lure; marketplace/explorer links are constructed by us
// but still pass through the same gate for consistency.
import { el } from '../dom.js'
import { checkUrl } from '../blocklist.js'

export function safeLink(href, label, { className } = {}) {
  const a = el('a', {
    href, class: className, target: '_blank', rel: 'noopener noreferrer',
    onclick: async (e) => {
      e.preventDefault()
      const v = await checkUrl(href)
      if (v.verdict === 'blocked' || v.verdict === 'fuzzy') {
        if (!confirm(`⛔ BLOCKED LINK\n\n${v.reason}\n\n${href}\n\nThis destination is on a phishing blocklist. Opening it can lead to wallet-draining sites.\n\nOpen anyway? (not recommended)`)) return
      }
      window.open(href, '_blank', 'noopener,noreferrer')
    },
  }, label)
  return a
}
