import { el, replace } from '../dom.js'
import { CHAINS } from '../config.js'
import { keyOf } from '../indexer.js'
import { hiddenSet, saveHidden, hiddenContracts, saveHiddenContracts, contractKey, isHidden } from '../flex.js'

// <img> with gateway-fallback: advance through candidates on error, then
// degrade to a text placeholder. All hosts are https (enforced by CSP img-src).
export function fallbackImg(candidates, attrs = {}) {
  if (!candidates.length) return el('div', { class: 'noimg' }, 'no image')
  let i = 0
  const img = el('img', {
    src: candidates[0], loading: 'lazy', alt: '',
    onerror: () => {
      i += 1
      if (i < candidates.length) img.src = candidates[i]
      else img.replaceWith(el('div', { class: 'noimg' }, 'no image'))
    },
    ...attrs,
  })
  return img
}

// filter/sort state lives here so it survives re-renders
export const filters = { q: '', chain: 'all', account: 'all', group: true }

export function renderGallery(container, state, onSelect, onUnhide) {
  if (state.scanning) {
    return replace(container,
      el('h2', {}, state.progress || 'Scanning…'),
      el('div', { class: 'grid' }, Array.from({ length: 8 }, () => el('div', { class: 'skel' }))))
  }
  if (!state.nfts.length) {
    return replace(container,
      state.scanErrors?.length
        ? el('div', { class: 'approw danger' }, el('span', { style: 'flex:1' },
            `⚠ ${state.scanErrors.length} indexer request(s) failed — this gallery may be incomplete. Try Rescan.`))
        : null,
      el('div', { class: 'empty' },
        state.connected
          ? `No NFTs found on ${CHAINS.map((c) => c.name).join(', ')} for accounts 0–4.`
          : `Connect your KeepKey Vault, then scan to see NFTs across your accounts (${CHAINS.length} chains).`))
  }
  const all = state.nfts.filter((n) => !n.spam && !isHidden(n, keyOf))
  const hidden = state.nfts.filter((n) => n.spam || isHidden(n, keyOf))
  const q = filters.q.trim().toLowerCase()
  const visible = all.filter((n) =>
    (filters.chain === 'all' || String(n.chainId) === filters.chain) &&
    (filters.account === 'all' || String(n.ownerIndex) === filters.account) &&
    (!q || n.name.toLowerCase().includes(q) || String(n.tokenId).includes(q) || (n.collectionName || '').toLowerCase().includes(q)))

  const rerender = () => renderGallery(container, state, onSelect, onUnhide)
  // Partial indexer failures must be visible too — a chain silently missing
  // from the results is indistinguishable from owning nothing there.
  const errBanner = state.scanErrors?.length
    ? el('div', { class: 'approw danger', style: 'margin-bottom:12px' },
        el('span', { style: 'flex:1' },
          `⚠ ${state.scanErrors.length} indexer request(s) failed — some holdings may be missing. `,
          el('span', { style: 'color:var(--dim)', title: state.scanErrors.join('\n') }, 'Rescan to retry.')))
    : null
  const bar = el('div', { class: 'filters' },
    el('input', { type: 'search', placeholder: 'search name, token id, collection…', value: filters.q,
      oninput: (e) => { filters.q = e.target.value; rerender(); container.querySelector('input[type=search]')?.focus() } }),
    el('select', { onchange: (e) => { filters.chain = e.target.value; rerender() } },
      el('option', { value: 'all', selected: filters.chain === 'all' || null }, 'all chains'),
      [...new Set(state.nfts.map((n) => n.chainId))].map((id) =>
        el('option', { value: String(id), selected: filters.chain === String(id) || null },
          state.nfts.find((n) => n.chainId === id).chainName))),
    el('select', { onchange: (e) => { filters.account = e.target.value; rerender() } },
      el('option', { value: 'all', selected: filters.account === 'all' || null }, 'all accounts'),
      [...new Set(state.nfts.map((n) => n.ownerIndex))].sort().map((i) =>
        el('option', { value: String(i), selected: filters.account === String(i) || null }, `account #${i}`))),
    el('button', { class: filters.group ? 'tab on' : 'tab', onclick: () => { filters.group = !filters.group; rerender() } },
      filters.group ? 'grouped by collection' : 'flat grid'),
    el('span', { style: 'color:var(--dim);font-size:12px' }, `${visible.length} of ${all.length}`))

  // group by collection (or chain when grouping is off)
  const groups = {}
  visible.forEach((n) => {
    const key = filters.group ? `${n.collectionName || 'Unnamed collection'} · ${n.chainName}` : n.chainName
    ;(groups[key] ||= []).push(n)
  })
  const sections = Object.entries(groups)
    .sort((a, b) => b[1].length - a[1].length)
    .flatMap(([title, list]) => [
      el('h2', { class: 'grouphead' }, `${title} — ${list.length}`,
        // one click removes an entire drainer contract, permanently
        el('button', {
          class: 'ghost hidegroup',
          title: 'Hide every token from these contracts',
          onclick: () => {
            const contracts = [...new Set(list.map(contractKey))]
            if (!confirm(`Hide all ${list.length} token(s) from ${contracts.length} contract(s) in "${title}"?\n\nFuture tokens from these contracts stay hidden too. Reversible in the hidden list.`)) return
            contracts.forEach((c) => hiddenContracts.add(c))
            saveHiddenContracts()
            onUnhide()
          },
        }, 'hide collection')),
      el('div', { class: 'grid' }, list.map((n) => {
        const card = el('div', { class: 'card', onclick: () => onSelect(n, card) },
          el('button', {
            class: 'quickhide', title: 'Hide this NFT',
            onclick: (e) => { e.stopPropagation(); hiddenSet.add(keyOf(n)); saveHidden(); onUnhide() },
          }, '✕'),
          fallbackImg(n.images),
          el('div', { class: 'meta' },
            el('div', { class: 'nm' }, n.name),
            el('div', { class: 'ch' }, `${n.chainName} · ${n.standard ?? ''}`,
              n.standard === 'ERC-1155' && n.quantity && n.quantity !== '1' ? ` · ×${n.quantity}` : '')))
        card.dataset.key = keyOf(n)
        return card
      })),
    ])
  sections.unshift(bar)
  if (errBanner) sections.unshift(errBanner)

  // Quarantine, presented like a spam-email folder: closed by default, one
  // folder row, and a standing warning about what these tokens are FOR.
  // Contents render as TEXT ONLY — their images are never fetched.
  let hiddenSection = null
  if (hidden.length) {
    const list = el('ul', { class: 'quarantine-list', hidden: 'hidden' }, hidden.map((n) =>
      el('li', {},
        el('span', {}, `${n.name.slice(0, 60)} · ${n.chainName} · `,
          n.spam
            ? el('span', { title: (n.spamReasons || []).join('; ') },
                `auto-flagged${n.spamReasons?.length ? ` — ${n.spamReasons[0]}` : ''}`)
            : 'hidden by you'),
        el('button', {
          class: 'ghost',
          onclick: () => {
            hiddenSet.delete(keyOf(n))
            hiddenContracts.delete(contractKey(n))
            saveHidden(); saveHiddenContracts()
            n.spam = false
            onUnhide()
          },
        }, 'restore'))))

    const folder = el('button', {
      class: 'quarantine-folder',
      'aria-expanded': 'false',
      onclick: () => {
        const open = list.hasAttribute('hidden')
        list.toggleAttribute('hidden', !open)
        folder.setAttribute('aria-expanded', String(open))
        folder.querySelector('.chev').textContent = open ? '▾' : '▸'
      },
    },
      el('span', { class: 'chev' }, '▸'),
      el('span', { class: 'qname' }, 'Spam & unsolicited'),
      el('span', { class: 'qcount' }, String(hidden.length)))

    hiddenSection = el('div', { id: 'hiddenSection' },
      el('div', { class: 'quarantine-warn' },
        el('span', { class: 'qicon', 'aria-hidden': 'true' }, '⚠'),
        el('span', {},
          el('b', {}, 'Scam and unsolicited NFTs usually want a signature. '),
          'They are bait — ',
          el('b', {}, 'Never sign anything you did not initiate, and never visit the links.'),
          ' Treat this like a spam folder: safe to leave here forever, and nothing here can do anything unless you interact with it.')),
      folder, list)
  }
  replace(container, sections, hiddenSection)
}
